insert into public.leyes (id,titulo,siglas,fecha_publicacion,fecha_ultima_reforma,vigente,temas_clave,url_original,tipo) values (E'ae592aba-a094-5c0c-af17-95a7ac408499',E'Anexo II. Metadatos Estructurales de la Norma Técnica para la elaboración de Metadatos de los Procesos de Producción de Información Estadística y Geográfica',E'METADATOS-II',null,null,true,ARRAY[E'SNIEG',E'INEGI',E'Información de Interés Nacional',E'Metadatos referenciales',E'Condición de llenado',E'DDI',E'SDMX']::text[],E'https://www.snieg.mx/Documentos/Normatividad/Vigente/anexos_II_ntmppieg.pdf',E'manual') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'd7564e97-88e9-5a0d-a303-4a64bb0ab1a6',E'Anexo II · 36 elementos estructurales · pág. 1',E'<section><p>El presente anexo tiene por objeto listar cada uno de los elementos de la especificación de Metadatos Estructurales para la descripción estandarizada de los archivos de datos de los Procesos de Producción que generan información desagregada a nivel microdato, así como su respectiva condición de llenado. Esta especificación de metadatos fue adaptada a partir de la Iniciativa de Documentación de Datos (DDI, por sus siglas en inglés) versión 2.0.</p><div class="overflow-x-auto"><table><thead><tr><th>Número</th><th>Sección</th><th>Apartado</th><th>Elemento</th><th>Condición de llenado</th></tr></thead><tbody><tr><td>1</td><td>Archivos de Base de datos</td><td>Descripción del archivo de base de datos</td><td>Nombre del archivo de Base de datos</td><td>Obligatorio</td></tr><tr><td>2</td><td>Archivos de Base de datos</td><td>Descripción del archivo de base de datos</td><td>Unidad y Área Administrativa responsable</td><td>Obligatorio</td></tr><tr><td>3</td><td>Archivos de Base de datos</td><td>Descripción del archivo de base de datos</td><td>Sitio de descarga de la Base de datos</td><td>Recomendado</td></tr><tr><td>4</td><td>Archivos de Base de datos</td><td>Descripción del archivo de base de datos</td><td>Contenido de la Base de datos</td><td>Obligatorio</td></tr><tr><td>5</td><td>Archivos de Base de datos</td><td>Descripción del archivo de base de datos</td><td>Cobertura temporal</td><td>Obligatorio</td></tr><tr><td>6</td><td>Archivos de Base de datos</td><td>Descripción del archivo de base de datos</td><td>Última fecha de publicación</td><td>Recomendado</td></tr><tr><td>7</td><td>Archivos de Base de datos</td><td>Descripción del archivo de base de datos</td><td>Versión de la Base de datos</td><td>Recomendado</td></tr><tr><td>8</td><t